150		if w := post("dev-1", "g1", []string{"banana", "apple"}); w.Code != http.StatusOK {
151			t.Fatal(w.Body.String())
152		}
153		if w := post("dev-2", "g2", []string{"cherry", "apple"}); w.Code != http.StatusOK {
154			t.Fatal(w.Body.String())
155		}
156		// Same id, identical content: idempotent created=false.
157		w, body := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtGSetBody("dev-1",
158			map[string]any{"id": "g1", "elements": []string{"apple", "banana"}}))
