160			t.Fatal(w.Body.String())
161		}
162		created := body["results"].([]any)[0].(map[string]any)["created"].(bool)
163		if created {
164			t.Fatal("identical repeat must be created=false")
165		}
166		// Same id, different elements: 409.
167		if w := post("dev-1", "g1", []string{"apple", "different"}); w.Code != http.StatusConflict {
