175		w, state := doRequest(t, h, http.MethodGet, "/v1/documents/doc/crdt/state")
176		if w.Code != http.StatusOK || state["type"] != "gset" {
177			t.Fatalf("%d %s", w.Code, w.Body.String())
178		}
179		got := state["value"].([]any)
180		want := []string{"apple", "banana", "cherry"}
181		if len(got) != len(want) {
182			t.Fatalf("elements = %v, want %v", got, want)
183		}
184		for i := range want {
185			if got[i].(string) != want[i] {
