382		}
383		req, err := http.NewRequest(method, srv.URL+path, rdr)
384		if err != nil {
385			t.Fatal(err)
386		}
387		if body != "" {
388			req.Header.Set("Content-Type", "application/json")
389		}
390		resp, err := srv.Client().Do(req)
391		if err != nil {
392			t.Fatalf("%s %s: %v", method, path, err)
393		}
394		return resp
395	}
