551	func TestCRDTRegisterVersionConflictIs409(t *testing.T) {
552		h, _ := newTestHandler(t)
553		registerDevice(t, h, "dev-1")
554	
555		post := func(id string, version int, value string) *httptest.ResponseRecorder {
556			t.Helper()
557			w, _ := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtRegisterBody("dev-1",
558				map[string]any{"id": id, "version": version, "value": value}))
559			return w
560		}
561		if w := post("a1", 5, "five"); w.Code != http.StatusOK {
562			t.Fatal(w.Body.String())
563		}
564		// A regressing version is a 409.
565		if w := post("a2", 4, "four"); w.Code != http.StatusConflict {
566			t.Fatalf("regression = %d, want 409", w.Code)
567		}
568		// An equal version with a fresh id is a 409 too.
569		if w := post("a3", 5, "five-again"); w.Code != http.StatusConflict {
570			t.Fatalf("stall = %d, want 409", w.Code)
571		}
572		// The identical repeat is idempotent, not a conflict.
573		w, body := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtRegisterBody("dev-1",
574			map[string]any{"id": "a1", "version": 5, "value": "five"}))
575		if w.Code != http.StatusOK {
576			t.Fatalf("idempotent repeat = %d %s", w.Code, w.Body.String())
577		}
578		if body["results"].([]any)[0].(map[string]any)["created"].(bool) {
579			t.Fatal("identical repeat must be created=false")
580		}
581		// Same id with a different value or version is a 409.
582		if w := post("a1", 5, "different"); w.Code != http.StatusConflict {
583			t.Fatalf("different value = %d, want 409", w.Code)
584		}
585		if w := post("a1", 6, "five"); w.Code != http.StatusConflict {
586			t.Fatalf("different version = %d, want 409", w.Code)
587		}
588	
589		// The rejections moved nothing.
590		w, state := doRequest(t, h, http.MethodGet, "/v1/documents/doc/crdt/state")
591		if w.Code != http.StatusOK || state["value"] != "five" {
592			t.Fatalf("state = %d %s", w.Code, w.Body.String())
593		}
594	}
