306	// An orset commit that moves the live element set pushes the new set to every
307	// subscriber; no-op removes, duplicate adds and idempotent replays push
308	// nothing.
309	func TestCRDTSubscribeORSetPushesOnlyRealChanges(t *testing.T) {
310		srv, _ := newWSTestServer(t)
311		setupSession(t, srv, "dev-1", "sess", "doc", 0)
312	
313		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
314		if conn == nil {
315			t.Fatalf("status = %d", hs.StatusCode)
316		}
317		defer conn.close()
318	
319		// First ever state: [apple].
320		if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("a1", "add", "apple"))); code != http.StatusOK {
321			t.Fatalf("submit = %d", code)
322		}
323		state := conn.readCRDTState()
324		if state.Type != "orset" {
325			t.Fatalf("type = %q, want orset", state.Type)
326		}
327		if got := crdtSetElements(t, state); len(got) != 1 || got[0] != "apple" {
328			t.Fatalf("elements = %v, want [apple]", got)
329		}
330	
331		// A duplicate add (new id, already-present element), a remove of a
332		// never-added element and an idempotent replay all move nothing and push
333		// nothing.
334		if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("a2", "add", "apple"))); code != http.StatusOK {
335			t.Fatalf("duplicate add = %d", code)
336		}
337		if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("r0", "remove", "ghost"))); code != http.StatusOK {
338			t.Fatalf("no-op remove = %d", code)
339		}
340		if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("a1", "add", "apple"))); code != http.StatusOK {
341			t.Fatalf("idempotent replay = %d", code)
342		}
343		conn.setReadDeadline(300 * time.Millisecond)
344		if _, _, _, ok := conn.readFrameMaybe(); ok {
345			t.Fatal("a no-op commit pushed a frame")
346		}
347		conn.clearReadDeadline()
348	
349		// A real remove pushes the empty set.
350		if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("r1", "remove", "apple"))); code != http.StatusOK {
351			t.Fatalf("remove = %d", code)
352		}
353		state = conn.readCRDTState()
354		if got := crdtSetElements(t, state); len(got) != 0 {
355			t.Fatalf("elements = %v, want []", got)
356		}
357	
358		// A re-add after the remove pushes the element again.
359		if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("a3", "add", "apple"))); code != http.StatusOK {
360			t.Fatalf("re-add = %d", code)
361		}
362		state = conn.readCRDTState()
363		if got := crdtSetElements(t, state); len(got) != 1 || got[0] != "apple" {
364			t.Fatalf("elements = %v, want [apple]", got)
365		}
366	}
