func TestCRDTORSetStatePersistsAcrossRestart(t *testing.T) {
	path := filepath.Join(t.TempDir(), "crdt.db")
	s1, err := app.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	h1 := NewHandler(s1)
	registerDevice(t, h1, "dev-1")
	w, _ := postJSON(t, h1, "/v1/documents/doc/crdt/ops", crdtORSetBody("dev-1",
		crdtORSetOp("a1", "add", "b"), crdtORSetOp("a2", "add", "a")))
	if w.Code != http.StatusOK {
		t.Fatal(w.Body.String())
	}
	w, _ = postJSON(t, h1, "/v1/documents/doc/crdt/ops", crdtORSetBody("dev-1",
		crdtORSetOp("r1", "remove", "b")))
	if w.Code != http.StatusOK {
		t.Fatal(w.Body.String())
	}
	if err := s1.Close(); err != nil {
		t.Fatal(err)
	}

	s2, err := app.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = s2.Close() }()
	h2 := NewHandler(s2)
	w, _ = doRequest(t, h2, http.MethodGet, "/v1/documents/doc/crdt/state")
	if w.Code != http.StatusOK {
		t.Fatalf("state after restart = %d", w.Code)
	}
	if got := w.Body.String(); got != `{"type":"orset","value":["a"]}`+"\n" {
		t.Fatalf("state after restart = %q", got)
	}
	// The remove's tombstone survived: re-adding b and reading still works,
	// and the idempotent replay of a1 is created=false.
	w, body := postJSON(t, h2, "/v1/documents/doc/crdt/ops", crdtORSetBody("dev-1",
		crdtORSetOp("a1", "add", "b")))
	if w.Code != http.StatusOK {
		t.Fatal(w.Body.String())
	}
	if body["results"].([]any)[0].(map[string]any)["created"].(bool) {
		t.Fatal("idempotent replay after restart must be created=false")
	}
}

// An orset commit that moves the live element set pushes the new set to every
// subscriber; no-op removes, duplicate adds and idempotent replays push
// nothing.
func TestCRDTSubscribeORSetPushesOnlyRealChanges(t *testing.T) {
	srv, _ := newWSTestServer(t)
	setupSession(t, srv, "dev-1", "sess", "doc", 0)

	conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
	if conn == nil {
		t.Fatalf("status = %d", hs.StatusCode)
	}
	defer conn.close()

	// First ever state: [apple].
	if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("a1", "add", "apple"))); code != http.StatusOK {
		t.Fatalf("submit = %d", code)
	}
	state := conn.readCRDTState()
	if state.Type != "orset" {
		t.Fatalf("type = %q, want orset", state.Type)
	}
	if got := crdtSetElements(t, state); len(got) != 1 || got[0] != "apple" {
		t.Fatalf("elements = %v, want [apple]", got)
	}

	// A duplicate add (new id, already-present element), a remove of a
	// never-added element and an idempotent replay all move nothing and push
	// nothing.
	if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("a2", "add", "apple"))); code != http.StatusOK {
		t.Fatalf("duplicate add = %d", code)
	}
	if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("r0", "remove", "ghost"))); code != http.StatusOK {
		t.Fatalf("no-op remove = %d", code)
	}
	if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("a1", "add", "apple"))); code != http.StatusOK {
		t.Fatalf("idempotent replay = %d", code)
	}
	conn.setReadDeadline(300 * time.Millisecond)
	if _, _, _, ok := conn.readFrameMaybe(); ok {
		t.Fatal("a no-op commit pushed a frame")
	}
	conn.clearReadDeadline()

	// A real remove pushes the empty set.
	if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("r1", "remove", "apple"))); code != http.StatusOK {
		t.Fatalf("remove = %d", code)
	}
	state = conn.readCRDTState()
	if got := crdtSetElements(t, state); len(got) != 0 {
		t.Fatalf("elements = %v, want []", got)
	}

	// A re-add after the remove pushes the element again.
	if code := postCRDTOps(t, srv, "doc", crdtORSetBody("dev-1", crdtORSetOp("a3", "add", "apple"))); code != http.StatusOK {
		t.Fatalf("re-add = %d", code)
	}
	state = conn.readCRDTState()
	if got := crdtSetElements(t, state); len(got) != 1 || got[0] != "apple" {
		t.Fatalf("elements = %v, want [apple]", got)
	}
}

package server

import (
	"encoding/json"
	"errors"
	"io"
	"mime"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// maxChunkBytes caps a single inbound chunk body.
const maxChunkBytes = 64 << 20

type attachmentRequest struct {
	ID         string          `json:"attachmentId"`
	TotalBytes json.RawMessage `json:"totalBytes"`
	ChunkSize  json.RawMessage `json:"chunkSize"`
	SHA256     string          `json:"sha256"`
}

// handleCreateAttachment registers a resumable chunked upload for the device
// in the path. The body is strict JSON carrying the stable attachment id, the
// declared total size and chunk size (positive integers) and the lowercase
// hex SHA-256 of the final content. Any malformed input is a 400 JSON error
// and writes nothing; an unregistered device is a 404; an id already taken —
// by another device, or by this device with different metadata — is a 409
// that leaves the original record untouched.
func handleCreateAttachment(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty

	var req attachmentRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.ID == "" {
		writeError(w, http.StatusBadRequest, "attachmentId must be a non-empty string")
		return
	}
	totalBytes, ok := parsePositiveInt(req.TotalBytes)
	if !ok {
		writeError(w, http.StatusBadRequest, "totalBytes must be a positive integer")
		return
	}
	chunkSize, ok := parsePositiveInt(req.ChunkSize)
	if !ok {
		writeError(w, http.StatusBadRequest, "chunkSize must be a positive integer")
		return
	}
	if !isLowerHexSHA256(req.SHA256) {
		writeError(w, http.StatusBadRequest, "sha256 must be 64 lowercase hexadecimal characters")
		return
	}

	created, err := s.CreateAttachment(deviceID, store.Attachment{
		ID:         req.ID,
		TotalBytes: totalBytes,
		ChunkSize:  chunkSize,
		SHA256:     req.SHA256,
	})
	if err != nil {
		var conflict *store.ErrAttachmentConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "attachmentId already exists with a different owner or metadata: "+conflict.ID)
		default:
			writeError(w, http.StatusInternalServerError, "failed to create attachment")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"attachmentId": req.ID, "created": created})
}

// handlePutChunk stores one binary chunk of an upload. The request must be
// application/octet-stream; the index is zero-based and chunks may arrive in
// any order. An unknown attachment is a 404 and a non-creator device a 403; a
// wrong content type, an out-of-range index, a short non-final chunk or a
// final chunk beyond the declared total is a 400 — none of these write
// anything. Re-submitting identical bytes is idempotent; different bytes for
// the same index are a 409 and the first content is kept. Once the upload is
// finished it is sealed: every further chunk write, even a byte-identical
// one, is a 409 and the stored content is unchanged.
func handlePutChunk(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")         // route pattern + guard guarantee non-empty
	attachmentID := r.PathValue("attachmentId") // route pattern + guard guarantee non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/octet-stream" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/octet-stream")
		return
	}

	index, ok := parseCursorPath(r.PathValue("index"))
	if !ok {
		writeError(w, http.StatusBadRequest, "chunk index must be a non-negative integer")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxChunkBytes+1)
	data, err := io.ReadAll(r.Body)
	if err != nil || int64(len(data)) > maxChunkBytes {
		writeError(w, http.StatusBadRequest, "chunk body is too large")
		return
	}

	created, err := s.PutChunk(deviceID, attachmentID, index, data)
	if err != nil {
		var invalid *store.ErrChunkInvalid
		var conflict *store.ErrChunkConflict
		switch {
		case errors.Is(err, store.ErrAttachmentNotFound):
			writeError(w, http.StatusNotFound, "attachment not found")
		case errors.Is(err, store.ErrAttachmentForbidden):
			writeError(w, http.StatusForbidden, "attachment belongs to another device")
		case errors.Is(err, store.ErrAttachmentSealed):
			writeError(w, http.StatusConflict, "attachment is complete and no longer accepts chunks")
		case errors.As(err, &invalid):
			writeError(w, http.StatusBadRequest, invalid.Reason)
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "chunk already exists with different content")
		default:
			writeError(w, http.StatusInternalServerError, "failed to store chunk")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"index": index, "created": created})
}

// handleCompleteAttachment seals an upload. Only the creating device may
// finish it (others get a 403; an unknown attachment a 404). Missing chunks
// or a total-length mismatch are a 409 and leave the upload resumable; a
// digest mismatch is a 422 and leaves it incomplete. When another finished
// attachment already holds the same digest and size, the content is reused
// without copying bytes (reused=true); the same digest at a different size is
// a 409. A successful or repeated finish returns the same recorded result.
func handleCompleteAttachment(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")         // route pattern + guard guarantee non-empty
	attachmentID := r.PathValue("attachmentId") // route pattern + guard guarantee non-empty

	result, err := s.CompleteAttachment(deviceID, attachmentID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrAttachmentNotFound):
			writeError(w, http.StatusNotFound, "attachment not found")
		case errors.Is(err, store.ErrAttachmentForbidden):
			writeError(w, http.StatusForbidden, "attachment belongs to another device")
		case errors.Is(err, store.ErrAttachmentIncomplete):
			writeError(w, http.StatusConflict, "chunks are missing or do not add up to the declared total")
		case errors.Is(err, store.ErrAttachmentDigestMismatch):
			writeError(w, http.StatusUnprocessableEntity, "assembled content does not match the declared sha256")
		case errors.Is(err, store.ErrAttachmentDigestConflict):
			writeError(w, http.StatusConflict, "a completed content with the same digest but a different size exists")
		default:
			writeError(w, http.StatusInternalServerError, "failed to complete attachment")
		}
		return
	}

	writeJSON(w, http.StatusOK, result)
}

// handleGetAttachment returns the creator's view of an upload: the original
// metadata, the sorted indices received so far and the completion status. A
// non-creator device gets a 403, an unknown attachment a 404.
func handleGetAttachment(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")         // route pattern + guard guarantee non-empty
	attachmentID := r.PathValue("attachmentId") // route pattern + guard guarantee non-empty

	a, indices, err := s.GetAttachment(deviceID, attachmentID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrAttachmentNotFound):
			writeError(w, http.StatusNotFound, "attachment not found")
		case errors.Is(err, store.ErrAttachmentForbidden):
			writeError(w, http.StatusForbidden, "attachment belongs to another device")
		default:
			writeError(w, http.StatusInternalServerError, "failed to load attachment")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"attachmentId":   a.ID,
		"totalBytes":     a.TotalBytes,
		"chunkSize":      a.ChunkSize,
		"sha256":         a.SHA256,
		"complete":       a.Complete,
		"receivedChunks": indices,
	})
}

// handleGetChunk streams one stored chunk back to the creator. An empty
// identifier is rejected by the path guard; an illegal index is a 400; an
// unknown attachment or a chunk that never arrived is a 404; a non-creator
// device is a 403.
func handleGetChunk(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")         // route pattern + guard guarantee non-empty
	attachmentID := r.PathValue("attachmentId") // route pattern + guard guarantee non-empty

	index, ok := parseCursorPath(r.PathValue("index"))
	if !ok {
		writeError(w, http.StatusBadRequest, "chunk index must be a non-negative integer")
		return
	}

	data, err := s.GetAttachmentChunk(deviceID, attachmentID, index)
	if err != nil {
		var invalid *store.ErrChunkInvalid
		switch {
		case errors.Is(err, store.ErrAttachmentNotFound):
			writeError(w, http.StatusNotFound, "attachment not found")
		case errors.Is(err, store.ErrChunkNotFound):
			writeError(w, http.StatusNotFound, "chunk not found")
		case errors.Is(err, store.ErrAttachmentForbidden):
			writeError(w, http.StatusForbidden, "attachment belongs to another device")
		case errors.As(err, &invalid):
			writeError(w, http.StatusBadRequest, invalid.Reason)
		default:
			writeError(w, http.StatusInternalServerError, "failed to load chunk")
		}
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(data)
}

// isLowerHexSHA256 reports whether s is exactly 64 lowercase hex characters.
func isLowerHexSHA256(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, c := range s {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// crdtOpIn is one element of a CRDT submission. Exactly one content shape is
// meaningful depending on the declared document type: value for a counter,
// elements for a grow-only set, value plus version for a register, action
// plus element for an observed-remove set.
type crdtOpIn struct {
	ID       string          `json:"id"`
	Value    json.RawMessage `json:"value"`
	Elements []string        `json:"elements"`
	Version  json.RawMessage `json:"version"`
	Action   string          `json:"action"`
	Element  string          `json:"element"`
}

// crdtOpsRequest is the body of POST .../crdt/ops.
type crdtOpsRequest struct {
	DeviceID string     `json:"deviceId"`
	Type     string     `json:"type"`
	Ops      []crdtOpIn `json:"ops"`
}

// handleCRDTOps accepts a batch of CRDT operations for a document.
//
// The batch declares the document's type; the first accepted batch fixes it
// to counter, gset, register or orset and every later batch must declare the
// same type. Two batches racing to declare different types serialize in one
// transaction: exactly one takes effect and the other is a 409 that writes
// nothing.
//
// The strict body contract matches the other JSON endpoints: application/json,
// one JSON value, no trailing content, a non-empty deviceId, a valid type, a
// non-empty ops array of elements with non-empty ids, no in-batch duplicate
// ids, and type-correct content (counter: an integer value; gset: an elements
// array; register: any JSON value — null included — plus a non-negative
// integer version; orset: action "add" or "remove" plus a non-empty string
// element). Any violation is a 400 with zero writes.
func handleCRDTOps(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req crdtOpsRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.Type != crdt.TypeCounter && req.Type != crdt.TypeGSet && req.Type != crdt.TypeRegister && req.Type != crdt.TypeORSet {
		writeError(w, http.StatusBadRequest, `type must be "counter", "gset", "register" or "orset"`)
		return
	}
	if len(req.Ops) == 0 {
		writeError(w, http.StatusBadRequest, "ops must be a non-empty array")
		return
	}

	ops := make([]crdt.Op, len(req.Ops))
	seen := make(map[string]struct{}, len(req.Ops))
	for i, op := range req.Ops {
		if op.ID == "" {
			writeError(w, http.StatusBadRequest, "each op must have a non-empty string id")
			return
		}
		if _, dup := seen[op.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate op id within batch: "+op.ID)
			return
		}
		seen[op.ID] = struct{}{}

		crdtOp := crdt.Op{ID: op.ID, DeviceID: req.DeviceID}
		switch req.Type {
		case crdt.TypeCounter:
			v, ok := parseNonNegativeInt(op.Value)
			if !ok {
				writeError(w, http.StatusBadRequest, "each counter op must carry an integer value >= 0")
				return
			}
			// Re-marshal the canonical integer so idempotency compares the
			// decoded value rather than the client's literal formatting.
			raw, _ := json.Marshal(v)
			crdtOp.Value = raw
		case crdt.TypeGSet:
			if len(op.Elements) == 0 {
				writeError(w, http.StatusBadRequest, "each gset op must add at least one element")
				return
			}
			for _, element := range op.Elements {
				if element == "" {
					writeError(w, http.StatusBadRequest, "gset elements must be non-empty strings")
					return
				}
			}
			crdtOp.Elements = op.Elements
		case crdt.TypeRegister:
			// The value may be any JSON, null included; only an absent field
			// (a nil RawMessage — an explicit null decodes to the bytes
			// "null") is a missing field. The value is stored verbatim.
			if op.Value == nil {
				writeError(w, http.StatusBadRequest, "each register op must carry a value")
				return
			}
			v, ok := parseNonNegativeInt(op.Version)
			if !ok {
				writeError(w, http.StatusBadRequest, "each register op must carry an integer version >= 0")
				return
			}
			crdtOp.Value = op.Value
			crdtOp.Version = v
		case crdt.TypeORSet:
			if op.Action != crdt.ORSetAdd && op.Action != crdt.ORSetRemove {
				writeError(w, http.StatusBadRequest, `each orset op must carry action "add" or "remove"`)
				return
			}
			if op.Element == "" {
				writeError(w, http.StatusBadRequest, "each orset op must carry a non-empty string element")
				return
			}
			crdtOp.Action = op.Action
			crdtOp.Element = op.Element
		}
		ops[i] = crdtOp
	}

	results, err := s.SubmitCRDTOps(documentID, req.Type, ops)
	if err != nil {
		var conflict *crdt.ErrConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, conflict.Error())
		default:
			writeError(w, http.StatusInternalServerError, "failed to commit crdt ops")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

// handleCRDTState returns the document's current type and merged result. A
// document with no committed operations has no state yet and answers 404.
func handleCRDTState(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	state, err := s.GetCRDTState(documentID)
	if err != nil {
		if errors.Is(err, crdt.ErrNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt state")
		return
	}

	writeCRDTState(w, state)
}

// handleSessionCRDTState is the session-scoped view of the document-level
// state read:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state
//
// The read identity is entirely the existing session (no new auth): the
// session's owning device is the credential and the validation order matches
// the other session-scoped reads exactly — request shape (400, enforced by the
// route and path guard before this handler), then session existence
// (404 JSON for a session that never existed or was deleted), then the
// session device's permission for the document (403 JSON with no state
// content), and finally the document's CRDT state. A document without any
// committed CRDT operation is the same 404 JSON as the document-level read, so
// a deleted session, an unknown document-state and a revoked permission remain
// three independent answers.
//
// On success the body is byte-for-byte the document-level state read's body
// (writeCRDTState): compact single-line JSON, keys type then value, one
// trailing newline. The endpoint is read-only: it renders the state derived by
// the store without advancing a cursor, writing a change, registering a
// subscription or affecting CRDT type fixation, idempotency or persistence; a
// restart changes neither the answer nor the status codes.
func handleSessionCRDTState(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	state, err := s.GetCRDTState(documentID)
	if err != nil {
		if errors.Is(err, crdt.ErrNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt state")
		return
	}

	writeCRDTState(w, state)
}

// writeCRDTState renders a CRDT state exactly as every state reader must:
// compact single-line JSON with the keys in type, value order, terminated by a
// newline (the json.Encoder output), shared by the document-level read, the
// session-scoped read and — via marshalCRDTState — the subscription push
// frames, so the three can be compared byte-for-byte.
func writeCRDTState(w http.ResponseWriter, state crdt.State) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(marshalCRDTState(state))
}

// marshalCRDTState encodes a CRDT state the single way every surface emits it:
// compact single-line JSON with the keys in type, value order and one trailing
// newline. The value is embedded as native JSON (a number, an array, or a
// register's arbitrary JSON value) rather than an escaped blob.
func marshalCRDTState(state crdt.State) []byte {
	var buf strings.Builder
	enc := json.NewEncoder(&buf)
	_ = enc.Encode(map[string]any{
		"type":  state.Type,
		"value": json.RawMessage(state.Value),
	})
	return []byte(buf.String())
}

// malformedCRDTPath reports whether p targets the CRDT namespace but is not at
// one of the four exact endpoints:
//
//	POST     /v1/documents/{documentID}/crdt/ops
//	GET      /v1/documents/{documentID}/crdt/state
//	POST     /v1/documents/{documentID}/crdt/compact
//	GET      /v1/documents/{documentID}/crdt/snapshot
//
// A missing/empty document id, a trailing slash, extra path segments, or a
// "crdt" segment in any position short of that shape is a malformed 400 rather
// than ServeMux's redirect or plain-text 404/405, so the new endpoints never
// redirect or emit HTML. The keyword is matched only past the documentID
// position, so a document literally named "crdt" keeps its ordinary routes.
func malformedCRDTPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg == "crdt" && i > 0 {
			if len(segs) != 3 || segs[0] == "" {
				return true
			}
			switch segs[2] {
			case "ops", "state", "compact", "snapshot":
				return false
			default:
				return true
			}
		}
	}
	return false
}

